"""PL-03 step 2: whole-period summary of each ticker."""

from __future__ import annotations

from statistics import mean, stdev

from risk.types import TickerSummary, VolSeries


def summary_stats(vol: VolSeries, periods_per_year: int = 252) -> tuple[TickerSummary, ...]:
    """Each ticker's return, volatility, Sharpe and last vol (spine: daily mean and stdev)."""
    del periods_per_year  # the spine reports daily figures; M1-T11 annualizes them
    if len(vol.returns.dates) < 2:
        raise ValueError("summary needs at least two returns")
    summaries = []
    for ticker in vol.returns.tickers:
        series = vol.returns.values[ticker]
        daily_mean, daily_vol = mean(series), stdev(series)
        summaries.append(
            TickerSummary(
                ticker=ticker,
                ann_return=daily_mean,
                ann_vol=daily_vol,
                sharpe=daily_mean / daily_vol if daily_vol else 0.0,
                last_vol=vol.values[ticker][-1],
            )
        )
    return tuple(summaries)
