from __future__ import annotations

import pytest

from risk.summary import summary_stats
from risk.types import Returns, VolSeries

DATES = ("2024-01-03", "2024-01-04", "2024-01-05", "2024-01-08", "2024-01-09")


def vol(returns: dict[str, tuple[float, ...]], last: float | None) -> VolSeries:
    dates = DATES[: len(next(iter(returns.values())))]
    source = Returns(
        base_date="2024-01-02", dates=dates, tickers=tuple(sorted(returns)), values=returns
    )
    values = {ticker: (None,) * (len(dates) - 1) + (last,) for ticker in returns}
    return VolSeries(returns=source, window=len(dates) - 1, annualized=True, values=values)


def test_daily_mean_stdev_their_ratio_and_the_last_vol():
    (summary,) = summary_stats(vol({"A": (0.01, 0.03, 0.05, -0.01, 0.0)}, 0.42))
    assert summary.ticker == "A"
    assert summary.ann_return == pytest.approx(0.016)
    assert summary.ann_vol == pytest.approx(0.0240831892)
    assert summary.sharpe == pytest.approx(0.6643638)
    assert summary.last_vol == 0.42


def test_one_summary_per_ticker_in_ticker_order():
    result = summary_stats(vol({"B": (0.01, 0.02), "A": (0.0, 0.01)}, None))
    assert [s.ticker for s in result] == ["A", "B"]
    assert result[0].last_vol is None


def test_flat_returns_give_zero_sharpe():
    (summary,) = summary_stats(vol({"A": (0.01, 0.01, 0.01)}, 0.0))
    assert summary.ann_vol == 0.0
    assert summary.sharpe == 0.0


def test_fewer_than_two_returns_is_a_value_error():
    with pytest.raises(ValueError, match="at least two returns"):
        summary_stats(vol({"A": (0.01,)}, None))
"""Intent tests for risk.summary_stats (M1-T11): RISK-04, TC-07."""

from __future__ import annotations

import math

import pytest

from risk.summary import summary_stats
from risk.types import Returns, TickerSummary, VolSeries


def _returns(payload: dict) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={ticker: tuple(series) for ticker, series in payload["values"].items()},
    )


def _vol(payload: dict) -> VolSeries:
    return VolSeries(
        returns=_returns(payload["returns"]),
        window=payload["window"],
        annualized=payload["annualized"],
        values={ticker: tuple(series) for ticker, series in payload["values"].items()},
    )


def _by_ticker(summaries) -> dict[str, TickerSummary]:
    return {s.ticker: s for s in summaries}


@pytest.mark.intent
def test_tc07_whole_period_summary(golden):
    data, expected = golden("risk", "TC-07")
    tol = expected["tol"]

    result = summary_stats(_vol(data["vol"]))

    assert isinstance(result, tuple)
    assert all(isinstance(s, TickerSummary) for s in result)
    got = _by_ticker(result)
    assert set(got) == {row["ticker"] for row in expected["summary"]}
    for row in expected["summary"]:
        s = got[row["ticker"]]
        assert s.ann_return == pytest.approx(row["ann_return"], abs=tol, rel=0)
        assert s.ann_vol == pytest.approx(row["ann_vol"], abs=tol, rel=0)
        assert s.sharpe == pytest.approx(row["sharpe"], abs=tol, rel=0)
        if row["last_vol"] is None:
            assert s.last_vol is None
        else:
            assert s.last_vol is not None
            assert s.last_vol == pytest.approx(row["last_vol"], abs=tol, rel=0)


@pytest.mark.intent
def test_tc07_one_summary_per_ticker_in_ticker_order(golden):
    data, _ = golden("risk", "TC-07")
    vol = _vol(data["vol"])

    result = summary_stats(vol)

    assert tuple(s.ticker for s in result) == vol.returns.tickers


@pytest.mark.intent
def test_tc07_zero_volatility_gives_zero_sharpe(golden):
    data, expected = golden("risk", "TC-07")
    tol = expected["tol"]
    zero_vol_rows = [row for row in expected["summary"] if row["ann_vol"] == 0.0]
    assert zero_vol_rows

    got = _by_ticker(summary_stats(_vol(data["vol"])))

    for row in zero_vol_rows:
        s = got[row["ticker"]]
        assert s.ann_vol == pytest.approx(0.0, abs=tol, rel=0)
        assert s.sharpe == 0.0
        assert math.isfinite(s.sharpe)


@pytest.mark.intent
def test_tc07_periods_per_year_scales_return_and_volatility(golden):
    data, expected = golden("risk", "TC-07")
    tol = expected["tol"]
    periods = 365
    ratio = periods / 252

    got = _by_ticker(summary_stats(_vol(data["vol"]), periods_per_year=periods))

    for row in expected["summary"]:
        s = got[row["ticker"]]
        assert s.ann_return == pytest.approx(row["ann_return"] * ratio, abs=tol, rel=0)
        assert s.ann_vol == pytest.approx(row["ann_vol"] * math.sqrt(ratio), abs=tol, rel=0)
        assert s.sharpe == pytest.approx(row["sharpe"] * math.sqrt(ratio), abs=tol, rel=0)


@pytest.mark.intent
def test_fewer_than_two_returns_is_a_value_error(contract_sample):
    payload = contract_sample("risk.VolSeries")
    rp = payload["returns"]
    one = {
        "returns": {
            "base_date": rp["base_date"],
            "dates": rp["dates"][:1],
            "tickers": rp["tickers"],
            "values": {t: series[:1] for t, series in rp["values"].items()},
        },
        "window": payload["window"],
        "annualized": payload["annualized"],
        "values": {t: [None] for t in payload["values"]},
    }

    with pytest.raises(ValueError, match=r"(?i)(two|2|return)"):
        summary_stats(_vol(one))
"""The risk contract types: returns, volatility, the summary, the drawdown and the report."""

from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass


@dataclass(frozen=True)
class Returns:
    """Daily returns on the prices' dates after the first, which is `base_date`."""

    base_date: str
    dates: tuple[str, ...]
    tickers: tuple[str, ...]
    values: Mapping[str, tuple[float, ...]]

    def __post_init__(self) -> None:
        if list(self.dates) != sorted(set(self.dates)) or not all(
            self.base_date < day for day in self.dates
        ):
            raise ValueError("dates must be unique, ascending and after base_date")
        if list(self.tickers) != sorted(set(self.tickers)):
            raise ValueError("tickers must be unique and sorted")
        if set(self.values) != set(self.tickers):
            raise ValueError("values must have exactly one series per ticker")
        for ticker, series in self.values.items():
            if len(series) != len(self.dates):
                raise ValueError(f"{ticker}: expected one return per date")


@dataclass(frozen=True)
class VolSeries:
    """Rolling volatility aligned to `returns.dates`; None until `window` earlier returns exist."""

    returns: Returns
    window: int
    annualized: bool
    values: Mapping[str, tuple[float | None, ...]]

    def __post_init__(self) -> None:
        if set(self.values) != set(self.returns.tickers):
            raise ValueError("values must have exactly one series per ticker")
        for ticker, series in self.values.items():
            if len(series) != len(self.returns.dates):
                raise ValueError(f"{ticker}: expected one value per return date")
            if any(value is not None for value in series[: self.window]):
                raise ValueError(f"{ticker}: no value until {self.window} earlier returns exist")


@dataclass(frozen=True)
class TickerSummary:
    """Whole-period statistics of one ticker."""

    ticker: str
    ann_return: float
    ann_vol: float
    sharpe: float
    last_vol: float | None


@dataclass(frozen=True)
class Drawdown:
    """One ticker's worst fall from a peak; `depth` is at most 0."""

    ticker: str
    depth: float
    peak_date: str

    def __post_init__(self) -> None:
        if not self.depth <= 0:
            raise ValueError("depth must be at most 0")


@dataclass(frozen=True)
class Report:
    """The written report: its path and one row per ticker, as in the file."""

    path: str
    rows: tuple[Mapping[str, object], ...]
